export const meta = {
  name: 'someguy-role-map',
  description: 'Map whether the someguy delegated-routing sidecar is on the upload/pin/publish/resolve critical path in CipherBox',
  phases: [{ title: 'Map', detail: 'parallel readers over ipfs/ipns/routing/kubo-config' }],
}

phase('Map')

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['area', 'onCriticalPath', 'summary', 'evidence'],
  properties: {
    area: { type: 'string' },
    onCriticalPath: { type: 'string', enum: ['yes', 'no', 'indirect', 'partial'] },
    summary: { type: 'string', description: 'Plain-language conclusion about someguy involvement and latency impact' },
    evidence: { type: 'array', items: { type: 'string' }, description: 'file:line citations' },
  },
}

const tasks = [
  {
    area: 'upload-pin-path',
    prompt: `Repo: CipherBox, a NestJS API under apps/api. The stack has a "someguy" delegated-routing sidecar reachable at DELEGATED_ROUTING_URL=http://someguy:8190, and a Kubo IPFS node.
Question: does the SYNCHRONOUS file-upload / IPFS pin server-side path (POST /ipfs/upload -> Kubo pin add) route through someguy, or is announcing/providing the CID to the DHT done ASYNCHRONOUSLY (off the synchronous pin path)?
Read the apps/api IPFS module: the controller, the service, and the pinning provider implementations (local/Kubo provider). Find exactly what the "pin" operation does and whether it blocks on any delegated-routing / DHT provide call. The Prometheus metric cipherbox_ipfs_ipns_duration_seconds{operation="pin"} times this. Return file:line evidence.`,
  },
  {
    area: 'ipns-publish-resolve-fallback',
    prompt: `Repo: CipherBox, NestJS API under apps/api. There is a "someguy" delegated-routing service at DELEGATED_ROUTING_URL=http://someguy:8190 and a fallback DELEGATED_ROUTING_FALLBACK_URL=https://delegated-ipfs.dev.
Question: how does the API use delegated routing (someguy) for IPNS PUBLISH and IPNS RESOLVE, and under what conditions does it FALL BACK to the public delegated-ipfs.dev endpoint? Read the apps/api ipns module and any delegated-routing client/service/provider. Identify: (1) is someguy on the publish path, the resolve path, or both; (2) what triggers fallback (timeout? error? value?), (3) what the fallback latency cost would be (public internet round-trip vs local sidecar). Note metrics cipherbox_delegated_routing_requests_total and cipherbox_delegated_routing_fallbacks_total. Return file:line evidence.`,
  },
  {
    area: 'kubo-routing-config',
    prompt: `Repo: CipherBox. The docker stack (docker/docker-compose.staging.yml and docker/docker-compose.yml) runs a Kubo IPFS node ("ipfs" service) and a "someguy" sidecar (SOMEGUY_DHT=accelerated) on a 2-vCPU host, each capped at cpus: '1.0'.
Question: is the Kubo daemon itself configured to delegate providing/finding to someguy (e.g. Routing.Type, Routing.Routers/DelegatedRouters), or does Kubo run its own DHT independently of someguy? Check the compose files, IPFS_PROFILE, any Kubo init/entrypoint scripts or config-setting commands in the repo, and the someguy/IPNS-related planning docs if helpful. Also assess the host-contention angle: someguy's accelerated DHT competes with Kubo for the 2 physical cores. Return file:line evidence and a clear yes/no on whether Kubo's provide/reprovide flows through someguy.`,
  },
]

const results = await parallel(
  tasks.map((t) => () => agent(t.prompt, { label: t.area, schema: SCHEMA }))
)
return results.filter(Boolean)

